    '9475369337045' => [
        'pl' => [ 'Cztery techniki w jednym: druk UV, UV DTF, DTG i DTF na materiałach sztywnych i tkaninach.', 'Efekty specjalne: wypukłości 3D do 7 mm, efekty lentikularne i biblioteka ponad 2000 tekstur.', 'Akcesoria: przystawka obrotowa do kubków i termosów oraz laminator do wykończeń hot foil.', 'Pozycjonowanie Pixel-scan™ i kolory zgodne z certyfikacją G7.', 'Współpracuje z laserami xTool – drukujesz, grawerujesz i tniesz w jednym procesie.' ],
