$to_html = static function ( $items ) {
    return wp_kses_post( '<ul>' . implode( '', array_map( static function ( $item ) { return '<li>' . esc_html( $item ) . '</li>'; }, $items ) ) . '</ul>' );
};
// Accessories keep their texts next to their compatibility in scripts/accessories.php.
foreach ( require __DIR__ . '/accessories.php' as $source_id => $accessory ) {
    if ( isset( $accessory['features'] ) ) {
        $translations[ $source_id ] = $accessory['features'];
    }
    if ( isset( $accessory['titles'] ) ) {
        $titles[ $source_id ] = $accessory['titles'];
    }
}
foreach ( $translations as $source_id => $languages ) {
    $posts = get_posts( [ 'post_type' => 'lasery_product', 'post_status' => 'publish', 'meta_key' => '_lasery_shopify_id', 'meta_value' => (string) $source_id, 'posts_per_page' => 2, 'fields' => 'ids' ] );
    if ( count( $posts ) !== 1 ) {
        WP_CLI::warning( 'Product ' . $source_id . ' is not uniquely published; skipped.' );
        continue;
    }
    foreach ( $languages as $language => $items ) {
        $key = '_lasery_description_' . $language;
        $html = $to_html( $items );
        // English uses the original post content as a fallback. Do not hide an existing edit.
        if ( 'en' === $language && ! metadata_exists( 'post', $posts[0], $key ) && '' !== trim( (string) get_post_field( 'post_content', $posts[0], 'raw' ) ) ) {
            continue;
        }
        if ( metadata_exists( 'post', $posts[0], $key ) ) {
            $placeholder = isset( $placeholders[ $source_id ][ $language ] ) ? $to_html( [ $placeholders[ $source_id ][ $language ] ] ) : null;
            if ( $placeholder !== get_post_meta( $posts[0], $key, true ) ) {
                continue;
            }
            if ( ! update_post_meta( $posts[0], $key, wp_slash( $html ) ) ) {
                WP_CLI::error( 'Could not replace description for ' . $source_id . ' / ' . $language );
            }
            continue;
        }
        if ( ! add_post_meta( $posts[0], $key, wp_slash( $html ), true ) ) {
            WP_CLI::error( 'Could not save description for ' . $source_id . ' / ' . $language );
        }
    }
    foreach ( $titles[ $source_id ] ?? [] as $language => $title ) {
        $key = '_lasery_title_' . $language;
        if ( ! metadata_exists( 'post', $posts[0], $key ) ) {
            if ( ! add_post_meta( $posts[0], $key, wp_slash( sanitize_text_field( $title ) ), true ) ) {
                WP_CLI::error( 'Could not save title for ' . $source_id . ' / ' . $language );
            }
        }
    }
    WP_CLI::success( 'Descriptions prepared for ' . $source_id );
}
